    isValid := FALSE;
ELSE
    FOR i := 1 TO nLen DO
        c := ipText[i];
        IF c >= 48 AND c <= 57 THEN
            IF segHasDigit THEN
                // To allow arbitrary leading zeros, segVal*10 can remain 0; but once value >255 reject
